-- Bloco 2/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('o_que_e_espiritismo', 'Em que datas foram fundadas por Allan Kardec, respectivamente, a ''Revista Espírita'' e a ''Sociedade Parisiense de Estudos Espíritas''?', '1º de janeiro de 1858 e 1º de abril de 1858.', '18 de abril de 1857 e 1º de janeiro de 1858.', '3 de outubro de 1858 e 25 de dezembro de 1858.', '15 de maio de 1857 e 18 de abril de 1859.', '1º de março de 1859 e 31 de março de 1860.', 'A', 'Allan Kardec lançou o primeiro número da Revista Espírita em 1º de janeiro de 1858 e fundou regularmente a Sociedade Parisiense de Estudos Espíritas em 1º de abril de 1858.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('o_que_e_espiritismo', 'Em que data e por qual causa orgânica desencarnou Allan Kardec em Paris, aos 64 anos de idade?', 'Em 18 de abril de 1869, vítima de pneumonia aguda.', 'Em 31 de março de 1869, fulminado pela ruptura de um aneurisma.', 'Em 2 de novembro de 1869, em decorrência de febre tifoide.', 'Em 3 de outubro de 1868, após um acidente vascular em viagem a Lyon.', 'Em 15 de janeiro de 1870, por insuficiência renal crônica.', 'B', 'Em 31 de março de 1869, enquanto preparava a mudança da sede para a rua e passagem Sainte-Anne e entregava um exemplar da Revista Espírita a um caixeiro de livraria, tombou fulminado pela ruptura de um aneurisma.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('o_que_e_espiritismo', 'Qual célebre astrônomo francês pronunciou um discurso memorável à beira do túmulo de Allan Kardec, chamando-o de ''o bom senso encarnado''?', 'Urbain Le Verrier.', 'François Arago.', 'Camille Flammarion.', 'Pierre-Simon Laplace.', 'Jean-Baptiste Biot.', 'C', 'No sepultamento de Allan Kardec, o astrônomo Camille Flammarion proferiu vibrante alocução, definindo o Codificador como ''o bom senso encarnado'' e ressaltando o caráter científico do Espiritismo.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
  ('o_que_e_espiritismo', 'Qual inscrição sintetizadora da lei de evolução encontra-se gravada no frontão do dólmen de Allan Kardec no cemitério do Père-Lachaise?', 'A fé inabalável é apenas aquela que pode encarar a razão face a face.', 'Fora da caridade não há salvação para o Espírito imortal.', 'Os mortos não morrem: apenas mudam de morada na casa do Pai.', 'Nascer, morrer, renascer ainda e progredir sempre, tal é a lei.', 'Trabalho, solidariedade e tolerância constituem o lema do espírita.', 'D', 'No alto do monumento druídico (dólmen) no cemitério do Père-Lachaise acha-se gravado o postulado fundamental: ''Nascer, morrer, renascer ainda e progredir sempre, tal é a lei''.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
  ('o_que_e_espiritismo', 'Segundo o Preâmbulo de ''O Que é o Espiritismo'', qual foi o objetivo principal de Allan Kardec ao publicar este livro sumário?', 'Substituir definitivamente a leitura de O Livro dos Espíritos e de O Livro dos Médiuns.', 'Criar um ritual litúrgico obrigatório para todas as sociedades espíritas da França.', 'Reunir apenas relatos de fenômenos físicos extraordinários para entreter o público.', 'Combater pessoalmente os sacerdotes e cientistas que atacavam sua reputação.', 'Oferecer um resumo sintético dos princípios da Doutrina e responder às principais objeções para quem deseja compreendê-la rapidamente.', 'E', 'No Preâmbulo, Kardec explica que publicou este resumo para dar em poucas palavras uma ideia exata do Espiritismo, fornecendo os pontos cardeais da ciência e respondendo às objeções mais comuns.', 'O Que é o Espiritismo - Preâmbulo', 'medio', true),
  ('o_que_e_espiritismo', 'No Capítulo I de ''O Que é o Espiritismo'' (''Pequena conferência espírita''), quais são os três interlocutores com quem o Adeptos dialoga sucessivamente?', 'O Crítico, o Cético e o Padre.', 'O Médico, o Juiz e o Filósofo.', 'O Materialista, o Cientista e o Pastor.', 'O Jornalista, o Magnetizador e o Bispo.', 'O Professor, o Ateo e o Monge.', 'A', 'O Capítulo I é dividido em três diálogos: o Primeiro Diálogo com O Crítico, o Segundo Diálogo com O Cético e o Terceiro Diálogo com O Padre.', 'O Que é o Espiritismo - Cap. I, Pequena conferência espírita', 'facil', true),
  ('o_que_e_espiritismo', 'No Primeiro Diálogo (''O Crítico''), que diferença fundamental o Visitante aponta entre a atitude do Crítico e a do Cético?', 'O Crítico crê nos Espíritos, enquanto o Cético acredita apenas em anjos.', 'O Cético duvida, mas busca esclarecer-se; o Crítico julga sem conhecer e procura ridicularizar aquilo que não estudou.', 'O Crítico realiza experiências práticas, enquanto o Cético apenas escreve panfletos.', 'O Cético é sempre inimigo da Ciência, ao passo que o Crítico defende as academias.', 'Não há diferença alguma, pois ambos negam a existência de Deus.', 'B', 'Kardec mostra no diálogo que o Crítico condena a priori e usa a zombaria sem haver lido nem observado nada, ao passo que o Cético sincero apresenta dúvidas racionais e deseja instruir-se.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'medio', true),
  ('o_que_e_espiritismo', 'No Primeiro Diálogo, quando o Crítico alega que os sábios e as academias oficiais condenaram o Espiritismo, que exemplos históricos o espírita lhe recorda?', 'A aceitação imediata do telégrafo óptico e da imprensa em toda a Europa.', 'A aprovação unânime das descobertas de Newton pela Igreja de Roma.', 'A rejeição inicial de grandes descobertas científicas, como o movimento da Terra por Galileu e a aplicação do vapor por Fulton.', 'O apoio financeiro concedido por Napoleão aos primeiros barcos a vapor.', 'A criação das universidades medievais pelos escolásticos.', 'C', 'Kardec lembra ao Crítico que corporações sábias também rejeitaram ou zombaram de Galileu, de Colombo e de Fulton com o barco a vapor, provando que a verdade independe de decretos acadêmicos.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'medio', true),
  ('o_que_e_espiritismo', 'Segundo argumenta Kardec no Primeiro Diálogo com o Crítico, qual foi o efeito prático das zombarias e dos ataques da imprensa burlesca contra o Espiritismo?', 'Reduziram drasticamente o número de adeptos nas grandes capitais.', 'Forçaram o fechamento temporário da Sociedade Parisiense de Estudos Espíritas.', 'Impediram a tradução das obras espíritas para outros idiomas europeus.', 'Despertaram a atenção do público, levando milhares de pessoas a examinar a Doutrina e aumentando o número de adeptos.', 'Fizeram com que os médiuns abandonassem a psicografia pelo receio do ridículo.', 'D', 'Kardec demonstra que as críticas levianas funcionaram como propaganda involuntária: aguando a curiosidade pública, fizeram com que pessoas sérias lessem as obras e se tornassem espíritas.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'dificil', true),
  ('o_que_e_espiritismo', 'Ao responder ao Crítico sobre os casos de charlatanismo e exploração financeira das manifestações, qual é a posição firme da Doutrina Espírita?', 'Tolera a cobrança moderada quando o médium é comprovadamente pobre.', 'Permite sessões pagas desde que a renda seja destinada a hospitais.', 'Autoriza os médiuns profissionais a cobrarem consultas particulares.', 'Reconhece que apenas os fenômenos de efeitos físicos podem ser remunerados.', 'Repudia formalmente qualquer exploração mercantil da mediunidade, declarando que o verdadeiro Espiritismo jamais faz de suas manifestações objeto de lucro.', 'E', 'Kardec enfatiza que o Espiritismo sério condena de modo absoluto os espetáculos pagos e o comércio da mediunidade, não podendo a Ciência verdadeira responder pelos abusos dos charlatães.', 'O Que é o Espiritismo - Cap. I, Primeiro Diálogo: O Crítico', 'dificil', true);
ON CONFLICT (statement) DO NOTHING;

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';